using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FrameVacuumFive {
 static Bounds World(Transform root){bool first=true;Bounds b=default;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){if(f.sharedMesh==null)continue;var local=f.sharedMesh.bounds;for(int i=0;i<8;i++){var v=local.center+Vector3.Scale(local.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));v=f.transform.TransformPoint(v);if(first){first=false;b=new Bounds(v,Vector3.zero);}else b.Encapsulate(v);}}return b;}
 public static object Run(){var p=Object.FindFirstObjectByType<PlayerController>();var c=p.characterCamera;var root=p.HeldInstrument.Find("Item In Hands/LVL_5");root.localScale=Vector3.one;root.localPosition=new Vector3(-.48f,2.02f,.94f);for(int n=0;n<5;n++){root.position+=c.ViewportToWorldPoint(new Vector3(.76f,.27f,1.1f))-World(root).center;var w=World(root);var a=c.WorldToViewportPoint(w.min);var b=c.WorldToViewportPoint(w.max);float h=Mathf.Abs(a.y-b.y);float width=Mathf.Abs(a.x-b.x);float scale=Mathf.Min(.40f/Mathf.Max(.01f,width),.45f/Mathf.Max(.01f,h));root.localScale*=Mathf.Clamp(scale,.6f,1.4f);}root.position+=c.ViewportToWorldPoint(new Vector3(.76f,.27f,1.1f))-World(root).center;EditorUtility.SetDirty(root);var preview=GameObject.Find("Temporary vacuum preview");if(preview!=null)Object.DestroyImmediate(preview);EditorSceneManager.SaveScene(root.gameObject.scene);return root.localScale.ToString();}
}
